mapper.select:
SELECT DATA_SCOPE AS dataScope, ORG_REF_ID AS orgRefId
FROM PEACH_ROLE_DATA_POLICY
WHERE TENANT_REF_ID = #{tenantRefId} AND APP_REF_ID = #{appRefId}
  AND ROLE_REF_ID = #{roleRefId} AND PERMISSION_REF_ID = #{permissionRefId}
  AND STATUS = 'ACTIVE' AND IS_DELETE = 0

mapper.update:
UPDATE PEACH_ROLE_DATA_POLICY
SET STATUS = 'DISABLED', IS_DELETE = 1,
    DELETED_AT = CURRENT_TIMESTAMP(3), VERSION = VERSION + 1
WHERE TENANT_REF_ID = #{tenantRefId} AND APP_REF_ID = #{appRefId}
  AND ROLE_REF_ID = #{roleRefId} AND PERMISSION_REF_ID = #{permissionRefId}
  AND STATUS = 'ACTIVE' AND IS_DELETE = 0

mapper.select:
SELECT FIELD_REF_ID AS fieldRefId, READ_EFFECT AS readEffect,
       WRITE_EFFECT AS writeEffect
FROM PEACH_ROLE_FIELD_POLICY
WHERE TENANT_REF_ID = #{tenantRefId} AND APP_REF_ID = #{appRefId}
  AND ROLE_REF_ID = #{roleRefId} AND PERMISSION_REF_ID = #{permissionRefId}
  AND STATUS = 'ACTIVE' AND IS_DELETE = 0

SELECT F.ID FROM PEACH_FIELD_DEFINITION F WHERE F.ID IN
#{fieldRefId}
AND F.RESOURCE_CODE = #{resourceCode} AND F.STATUS = 'ACTIVE' AND F.IS_DELETE = 0 AND (F.APP_REF_ID IS NULL OR F.APP_REF_ID = #{appRefId}) AND ((F.OWNER_TYPE = 'TENANT' AND F.TENANT_REF_ID = #{tenantRefId}) OR (F.OWNER_TYPE = 'SYSTEM' AND F.TENANT_REF_ID IS NULL AND F.DELEGABLE = 1))

mapper.update:
UPDATE PEACH_ROLE_FIELD_POLICY
SET STATUS = 'DISABLED', IS_DELETE = 1,
    DELETED_AT = CURRENT_TIMESTAMP(3), VERSION = VERSION + 1
WHERE TENANT_REF_ID = #{tenantRefId} AND APP_REF_ID = #{appRefId}
  AND ROLE_REF_ID = #{roleRefId} AND PERMISSION_REF_ID = #{permissionRefId}
  AND STATUS = 'ACTIVE' AND IS_DELETE = 0
